INSERT INTO DimDate (SK_DateID, DateValue, DateDesc, CalendarYearID, CalendarYearDesc, CalendarQtrID, CalendarQtrDesc, CalendarMonthID, CalendarMonthDesc, CalendarWeekID, CalendarWeekDesc, DayOfWeekNum, DayOfWeekDesc, FiscalYearID, FiscalYearDesc, FiscalQtrID, FiscalQtrDesc, HolidayFlag) SELECT SK_DateID, DateValue, DateDesc, CalendarYearID, CalendarYearDesc, CalendarQtrID, CalendarQtrDesc, CalendarMonthID, CalendarMonthDesc, CalendarWeekID, CalendarWeekDesc, DayOfWeekNum, DayOfWeekDesc, FiscalYearID, FiscalYearDesc, FiscalQtrID, FiscalQtrDesc, CASE WHEN UPPER(HolidayFlag) = 'TRUE' THEN TRUE ELSE FALSE END AS HolidayFlag FROM Source.Date;
